  text:{format:{type:'json_schema',strict:true,
   name:'cotironda_ai_central_lector_v2_d013',
   schema:firstSchema}}
 };
 let response:Response;
 try{
  response=await args.fetchImpl(API,{method:'POST',
   headers:{Authorization:'Bearer '+args.apiKey,'Content-Type':'application/json'},
   body:JSON.stringify(req),signal:AbortSignal.timeout(55000)});
 }catch(e){
  throw Error(e instanceof Error&&
   ['TimeoutError','AbortError'].includes(e.name)
   ?'ai_timeout':'ai_upstream_unavailable');
 }
 if(!response.ok){
  // Preserve only fixed HTTP categories, never log API credentials,
  // response bodies, raw prompts, or server-generated error text.
  const c=response.status;
  throw Error(c===401||c===403?'ai_credentials_rejected':
   c===429?'ai_rate_limited':
   c===400||c===404||c===422?'ai_request_rejected':
   c>=500?'ai_upstream_failure':'ai_upstream_rejected');
 }
 const length=Number(response.headers.get('content-length')??0);
 if(length>50000)throw Error('ai_response_too_large');
 let body:string;
 try{body=await response.text()}catch{throw Error('ai_response_read_failed')}
 if(body.length>50000)throw Error('ai_response_too_large');
 return extractJson(JSON.parse(body));
}
/** Llamador DEBE reservar cuota durable antes y persistir el resultado
 * una sola vez por HMAC fuente; este módulo NO registra ni envía mensajes.
 * El modelo nunca llama herramientas externas.
 */
export async function interpretarConIaCentralV2D013(args:{
 fuente:string;apiKey:string;model:'gpt-6-luna'|'gpt-6.1-sol';
 fetchImpl?:typeof fetch;
 onQuantityDiagnostic?:(code:DiagnosticoCantidadD013)=>void;
 zonaConfirmada?:string;
}):Promise<ResultadoLectura>{
 if(typeof args?.fuente!=='string'||args.fuente.length<1||
    args.fuente.length>12000||
    typeof args.apiKey!=='string'||!/^sk-[A-Za-z0-9_-]{16,}$/u.test(args.apiKey)||
    !MODEL_ALLOWED.has(args.model))
  return {estado:'rechazado',motivo:'entrada_o_credenciales_invalidas',pedido:null};
 try{
  const reader=await ask({apiKey:args.apiKey,model:args.model,
   source:args.fuente,fetchImpl:args.fetchImpl??fetch});
  if(!reader||typeof reader!=='object'||Array.isArray(reader))
   throw Error('bad_first');
  const first=reader as Record<string,unknown>;
  if(first.intencion!=='cotizar')
   return evaluarLecturaCentralUnicaD013(args.fuente,first,
    args.onQuantityDiagnostic);
  // Los offsets se derivan del ORIGINAL, nunca de una inferencia del modelo.
  const withEvidence=localizarEvidenciasV1(args.fuente,first);
  if(!withEvidence)
   return {estado:'rechazado',motivo:'citas_no_corresponden_al_original',pedido:null};
  return evaluarLecturaCentralUnicaD013(args.fuente,withEvidence,
   args.onQuantityDiagnostic,args.zonaConfirmada);
 }catch(e){
  // The application reports only a closed set of non-sensitive failure
  // codes so SQL can distinguish 401, rate limits, malformed schema,
  // timeouts and genuine reader disagreement. Never store the API body.
  const safe=new Set([
   'ai_timeout','ai_upstream_unavailable','ai_upstream_failure',
   'ai_credentials_rejected','ai_rate_limited','ai_request_rejected',
   'ai_upstream_rejected','ai_response_too_large','response_shape',
   'response_not_completed','response_no_message','response_bad_text',
   'response_bad_json','ai_response_read_failed','bad_first'
  ]);
  const reason=e instanceof Error&&safe.has(e.message)
    ?e.message:'modelo_no_disponible_o_salida_invalida';
  return {estado:'rechazado',motivo:reason,pedido:null};
 }
}


/** Reproducción de SOLO LECTURA de un pedido previamente autenticado por
 * recuperador privado. Hace una única inferencia IA, nunca SQL, ruteo,
 * almacenamiento, invitación ni WhatsApp. No devuelve contenido original
 * ni respuesta del modelo; únicamente una forma estructural sin números.
 */
export type DiagnosticoLecturaPrivadaD013=Readonly<{
 estado:'cantidad_inacreditable'|'sin_fallo_cantidad'|
 'esquema_invalido'|'citas_invalidas'|'modelo_no_disponible';
 detalle:InformeCantidadPrivadaD013|null;
}>;
export async function diagnosticarLecturaPrivadaD013(args:{
 fuente:string;apiKey:string;model:'gpt-6-luna'|'gpt-6.1-sol';
 fetchImpl?:typeof fetch;
}):Promise<DiagnosticoLecturaPrivadaD013>{
 const reply=(estado:DiagnosticoLecturaPrivadaD013['estado'],
   detalle:InformeCantidadPrivadaD013|null=null)=>
  Object.freeze({estado,detalle});
 if(typeof args?.fuente!=='string'||args.fuente.length<10||
  args.fuente.length>4000||typeof args.apiKey!=='string'||
  !/^sk-[A-Za-z0-9_-]{16,}$/u.test(args.apiKey)||
  !MODEL_ALLOWED.has(args.model))return reply('esquema_invalido');
 let raw:unknown;
 try{
  raw=await ask({apiKey:args.apiKey,model:args.model,source:args.fuente,
   fetchImpl:args.fetchImpl??fetch});
 }catch{return reply('modelo_no_disponible')}
 if(raw===null||typeof raw!=='object'||Array.isArray(raw))
  return reply('esquema_invalido');
 const model=raw as Record<string,unknown>;
 if(model.intencion!=='cotizar'||!Array.isArray(model.articulos)||
    model.articulos.length<1||model.articulos.length>200)
  return reply('esquema_invalido');
 const located=localizarEvidenciasV1(args.fuente,model);
 if(!located||!Array.isArray(located.articulos))
  return reply('citas_invalidas');
 for(let i=0;i<located.articulos.length;i++){
  const a=located.articulos[i];
  if(a===null||typeof a!=='object'||Array.isArray(a))continue;
  const item=a as Record<string,unknown>;
  const isolated=evaluarLecturaCentralUnicaD013(args.fuente,
   {...located,articulos:[item]});
  if(isolated.motivo!=='cantidad_sin_respaldo_en_fuente')continue;
  const evidence={
   inicio:Number(item.inicio),fin:Number(item.fin),
   evidencia:String(item.evidencia??''),citaCantidad:item.citaCantidad,
   cantidad:item.cantidad
  };
  const detail=resumirCantidadPrivadaD013(args.fuente,evidence,i);
  return detail?reply('cantidad_inacreditable',detail):
   reply('citas_invalidas');
 }
 return reply('sin_fallo_cantidad');
}

/** D013 V2-only: planner no rubro-gate; preserving locked M220. */
/** IA Central — orquestador semántico en SOMBRA (sin escrituras ni envíos).
 * Primer puente real Supabase→IA→catalogos→ruteo:
 * 1) interpreta libremente el mensaje Whapi YA verificado,
 * 2) lee un catálogo real SOLO vía RPC privado de service_role,
 * 3) clasifica rubros comerciales sin diccionario de nombres,
 * 4) propone proveedores y valida cada línea contra la lista fuente.
 *
 * La fase de preparación económica/WhatsApp será otra transacción SQL.
 * NO introducir fetch Whapi en este archivo.
 */
import {interpretarConIaCentralV2D013} from './cliente-openai-v2-d013.ts';
import {evaluarLecturaCentralUnicaD013,type DiagnosticoCantidadD013} from './contrato-v2-d013.ts';
import {validarSnapshotCatalogosMvp220} from './catalogo-supabase-mvp220.ts';
import {categorizarCatalogosCuradosD013} from './catalogo-curado-v2-d013.ts';
import {proponerRuteoCatalogoConIAV2,zonaIgual} from './ruteador-catalogos-v2-d013.ts';
import type {PropuestaPedido} from './contrato-v1.ts';
import type {ResultadoCatalogoV2} from './ruteador-catalogos-v2-d013.ts';
import type {ProveedorCatalogoV2} from './ruteador-catalogos-v2-d013.ts';

type Rpc= (name:string,params:Readonly<Record<string,string>>)=>
 Promise<{data:unknown;error:unknown}>;
type Modelo='gpt-6-luna'|'gpt-6.1-sol';
export type PlanMvp220=Readonly<{
 estado:'plan_validado_sin_envio'|'sin_catalogo_confirmado'|
 'requiere_aclaracion'|'rechazado';
 motivo:string;
 pregunta?:string;
 pedido:PropuestaPedido|null;
 ruteo:ResultadoCatalogoV2|null;
 /** Fuente del catálogo únicamente para el broker server-side. NO serializar al comprador. */
 catalogos:readonly ProveedorCatalogoV2[]|null;
 whatsappEnviado:false;
 baseModificada:false;
}>;
const KEY=/^[a-f0-9]{64}$/u;
const deny=(estado:PlanMvp220['estado'],motivo:string,pregunta?:string):PlanMvp220=>({
 estado,motivo,...(pregunta?{pregunta}:{}),pedido:null,ruteo:null,catalogos:null,whatsappEnviado:false,baseModificada:false
});
const matchCity=zonaIgual;
export async function planificarMensajeAutenticadoMvp220(args:{
 chatHmac:string;messageHmac:string;
 textoOriginal:string;
 autenticadoPorWebhook:boolean;
 apiKey:string;model:Modelo;
 rpc:Rpc;fetchImpl?:typeof fetch;
 onQuantityDiagnostic?:(code:DiagnosticoCantidadD013)=>void;
 localidadConfirmada?:string;pedidoContinuado?:unknown;
}):Promise<PlanMvp220>{
 if(!args||args.autenticadoPorWebhook!==true||
    !KEY.test(args.chatHmac)||!KEY.test(args.messageHmac)||
    typeof args.textoOriginal!=='string'||args.textoOriginal.length<10||
    args.textoOriginal.length>12000||typeof args.rpc!=='function')
  return deny('rechazado','origen_no_autorizado');
 // IMPORTANT: el webhook real aplica identidad/HMAC, persiste la fuente
 // y reserva su cuota ANTES de habilitar este worker. El booleano no
 // es autorización real; el RPC verifica identidad nuevamente.
 const interpreted=args.pedidoContinuado!==undefined
  ?validarContinuacionD013(args.textoOriginal,args.pedidoContinuado,args.localidadConfirmada)
  :await interpretarConIaCentralV2D013({
   fuente:args.textoOriginal,apiKey:args.apiKey,model:args.model,
   fetchImpl:args.fetchImpl,onQuantityDiagnostic:args.onQuantityDiagnostic,
   zonaConfirmada:args.localidadConfirmada
  });
 if(interpreted.estado==='requiere_aclaracion')
  return {...deny('requiere_aclaracion',interpreted.motivo,interpreted.pregunta),
   pedido:interpreted.motivo==='zona_de_entrega_faltante'?interpreted.pedido:null};
 if(interpreted.estado!=='listo_para_preparar'||!interpreted.pedido)
  return deny('rechazado',interpreted.motivo);
 const pedido=interpreted.pedido;
 const city=pedido.zona_entrega;
 if(!city)return deny('requiere_aclaracion','falta_localidad');
 let raw:unknown;
 try{
  const r=await args.rpc('cotironda_piloto_ia_catalogo_mvp220',{
   p_buyer_chat_hmac:args.chatHmac,p_delivery_city:city
  });
  if(r.error!==null&&r.error!==undefined)
   return deny('rechazado','catalogo_rpc_indisponible');
  raw=r.data;
 }catch{return deny('rechazado','catalogo_rpc_indisponible')}
 const catalog=validarSnapshotCatalogosMvp220(raw);
 if(!catalog||!matchCity(catalog.localidad,city))
  return deny('rechazado','catalogo_rpc_no_conciliado');
 if(catalog.proveedores.length===0)
  return deny('rechazado','sin_catalogos_consentidos');
 const classified=await categorizarCatalogosCuradosD013({
  snapshot:catalog,apiKey:args.apiKey,
  model:args.model,fetchImpl:args.fetchImpl
 });
 if(classified.estado==='catalogo_invalido')
  return deny('rechazado',classified.motivo);
 // En V2 la ÚNICA IA Central decide todos los ítems; nunca fragmentar
 // el pedido según supuestas diferencias entre lectores. El catálogo
 // aporta productos concretos y permisos, NO una nueva lectura del texto.
 const route=await proponerRuteoCatalogoConIAV2({
  pedido,proveedores:classified.proveedores,
  apiKey:args.apiKey,model:args.model,fetchImpl:args.fetchImpl
 });
 if(route.estado!=='ruteo_valido_para_preparacion')
  return deny('rechazado',route.motivo);
 if(route.propuestas.length===0)
  return deny('requiere_aclaracion','ningun_proveedor_para_la_lista');

 return {
  estado:'plan_validado_sin_envio',
  motivo:classified.estado==='catalogo_sin_confirmar'?
   'ruteo_sobre_catalogos_registrados_sin_confirmacion_formal':'ruteo_semantico_valido',
  pedido,ruteo:route,catalogos:classified.proveedores,whatsappEnviado:false,baseModificada:false
 };
}

/** Revalida estructura y evidencia, NO interpreta otra vez los materiales. */
export function validarContinuacionD013(original:string,snapshot:unknown,city?:string):ReturnType<typeof evaluarLecturaCentralUnicaD013>{
 const reject=()=>({estado:'rechazado' as const,motivo:'snapshot_invalido',pedido:null});
 if(!snapshot||typeof snapshot!=='object'||Array.isArray(snapshot)||
    typeof city!=='string'||city.trim().length<3||city.length>80||
    /[\u0000-\u001f]/u.test(city))return reject();
 const p=snapshot as Record<string,unknown>;
 if(p.intencion!=='cotizar'||p.zona_entrega!==null||
    !Array.isArray(p.articulos)||!Array.isArray(p.dudas)||p.dudas.length!==0)
  return reject();
 const articles=p.articulos.map(x=>x&&typeof x==='object'&&!Array.isArray(x)
  ?{...x,citaPresentacion:x.presentacion}:x);
 return evaluarLecturaCentralUnicaD013(original,
  {...p,articulos:articles,aclaracion_esencial:false},undefined,city);
}
